const CAT_CHAIRMAN = '\u4e3b\u59d4';
const CAT_REP = '\u5168\u4ee3';
const CAT_CITY = '\u5e02\u4ee3';
const FIELD_NAME = '\u59d3\u540d';
const FIELD_CATEGORY = '\u985e\u5225';
const FIELD_TARGETS = ['\u9054\u6a19\u6578', '\u9054\u6a19\u7968\u6578', '\u76ee\u6a19\u7968\u6578', '\u7968\u6578'];
const FIELD_CHAIRMAN_VOTE = '\u6295\u7d66\u4e3b\u59d4';
const FIELD_REP_VOTE = '\u6295\u7d66\u5168\u4ee3';
const FIELD_CITY_VOTE = '\u6295\u7d66\u5e02\u4ee3';
const DEFAULT_TARGET_VOTES = 300;
const CATEGORY_BY_NAME = {
  '\u8a31\u6728\u6842': CAT_CHAIRMAN,
  '\u9673\u6021\u6f54': CAT_REP,
  '\u90b1\u67cf\u745e': CAT_REP,
  '\u9ec3\u7f8e\u60e0': CAT_CITY,
  '\u8cf4\u79c0\u5982': CAT_CITY,
  '\u6797\u5fd7\u9d3b': CAT_CITY,
  '\u738b\u4fca\u5091': CAT_CITY,
  '\u9673\u4f69\u541b': CAT_CITY
};
function compact(value) { return String(value || '').replace(/\s+/g, '').trim(); }
function notionPropText(property) {
  if (!property) return '';
  const arr = property.title || property.rich_text;
  if (Array.isArray(arr)) return arr.map(t => t.plain_text || (t.text && t.text.content) || '').join('');
  if (property.select && property.select.name != null) return String(property.select.name);
  if (Array.isArray(property.multi_select)) return property.multi_select.map(s => s.name || '').join(', ');
  if (typeof property.number === 'number') return String(property.number);
  return '';
}
function notionPropNumber(property) {
  if (!property) return null;
  if (typeof property.number === 'number') return property.number;
  const parsed = Number(notionPropText(property));
  return Number.isFinite(parsed) ? parsed : null;
}
function findProp(json, names) {
  const props = json.properties || {};
  for (const name of names) if (props[name] != null) return props[name];
  const wanted = names.map(compact);
  for (const [key, value] of Object.entries(props)) if (wanted.includes(compact(key))) return value;
  return undefined;
}
function titleText(json) {
  const p = findProp(json, [FIELD_NAME, 'name', 'Name']) || Object.values(json.properties || {}).find(p => p.type === 'title');
  return notionPropText(p).trim();
}
function categoryText(json, candidateName) {
  const explicit = notionPropText(findProp(json, [FIELD_CATEGORY, 'category', 'Category'])).trim();
  if ([CAT_CHAIRMAN, CAT_REP, CAT_CITY].includes(explicit)) return explicit;
  return CATEGORY_BY_NAME[candidateName] || '';
}
function targetVotes(json) {
  const value = notionPropNumber(findProp(json, FIELD_TARGETS));
  return value && value > 0 ? Math.floor(value) : DEFAULT_TARGET_VOTES;
}
function recordFieldText(json, fieldName) { return notionPropText(findProp(json, [fieldName])).trim(); }
const candidates = $('Get Vote Candidates').all().map(item => {
  const name = titleText(item.json);
  return { name, category: categoryText(item.json, name), votes: 0, targetVotes: targetVotes(item.json) };
}).filter(item => item.name);
const byName = new Map(candidates.map(item => [compact(item.name), item]));
const records = $('Get Vote Records').all();
for (const record of records) {
  const votedNames = [recordFieldText(record.json, FIELD_CHAIRMAN_VOTE), recordFieldText(record.json, FIELD_REP_VOTE), recordFieldText(record.json, FIELD_CITY_VOTE)].map(compact).filter(Boolean);
  for (const votedName of votedNames) {
    const candidate = byName.get(votedName);
    if (candidate) candidate.votes += 1;
  }
}
return [{ json: { success: true, candidates, totalVoters: 0, votedCount: records.length, recordCount: records.length, generatedAt: new Date().toISOString() } }];
